import{_ as n,C as t,o as s,c as d,E as a,a2 as i}from"./chunks/framework.Bx6eOp9J.js";const f=JSON.parse('{"title":"状态批量保存不是回滚事务：恢复证据的三个边界","description":"","frontmatter":{"title":"状态批量保存不是回滚事务：恢复证据的三个边界","date":"2026-10-23","column":"open-source-engineering","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"状态保存、恢复身份与待处理动作日志各能说明什么，为什么批量保存不能被当作异常回滚或外部效果的恰好一次执行？","research_question_en":"What do state saving, restore identity and pending-action logs establish, and why should batched saving not be treated as exception rollback or exactly-once external execution?","summary":"本地状态保存与外部工作事实需要不同的证据和恢复责任。","sources":"https://docs.openhands.dev/sdk/guides/convo-persistence.md, https://raw.githubusercontent.com/OpenHands/software-agent-sdk/60192ed54db73ac658ac1a07462916126c32d3a0/openhands-sdk/openhands/sdk/conversation/state.py, https://learn.microsoft.com/en-us/agent-framework/workflows/checkpoints?output=1, https://learn.microsoft.com/en-us/agent-framework/support/upgrade/python-1-13-0-workflow-checkpoint-upgrade-guide, https://learn.microsoft.com/en-us/agent-framework/concepts/workflows/builder-and-execution","pageClass":"runtime-v6-article","item_id":"SIG-20261023-001","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-23-sig-20261023-001-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-10-23-sig-20261023-001.md","filePath":"zh/engineering/2026-10-23-sig-20261023-001.md","lastUpdated":1792763845000}'),c={name:"zh/engineering/2026-10-23-sig-20261023-001.md"};function l(p,e,h,u,g,m){const r=t("ArticleCover"),o=t("ArticleTableScroll");return s(),d("div",null,[a(r,{image:"/assets/covers/daily-2026-10-23-sig-20261023-001-cover.png",kicker:"研究成果",title:"状态批量保存不是回滚事务：恢复证据的三个边界",summary:"本地状态保存与外部工作事实需要不同的证据和恢复责任。",version:"2026-10-23",languageHref:"/en/engineering/2026-10-23-sig-20261023-001",languageLabel:"English"}),a(o,{language:"zh"}),e[0]||(e[0]=i('<h1 id="状态批量保存不是回滚事务-恢复证据的三个边界" tabindex="-1">状态批量保存不是回滚事务：恢复证据的三个边界 <a class="header-anchor" href="#状态批量保存不是回滚事务-恢复证据的三个边界" aria-label="Permalink to &quot;状态批量保存不是回滚事务：恢复证据的三个边界&quot;">​</a></h1><p>在本轮隔离实验中，批处理块里的异常照常抛出，但保存钩子仍收到变更后的值9。把一组状态更新放进上下文管理器，只能由实际方法决定其含义；语法外观不能赋予它回滚事务的保证。恢复设计还面临更深一层问题：即使本地状态完整，外部动作究竟有没有发生，仍可能未知。</p><h2 id="异常之后保存了什么" tabindex="-1">异常之后保存了什么 <a class="header-anchor" href="#异常之后保存了什么" aria-label="Permalink to &quot;异常之后保存了什么&quot;">​</a></h2><p>本轮分析从 OpenHands（开放之手软件智能体框架）的固定源码提取未改动的方法体，执行17个场景：5个保存场景、8个动作匹配与构造历史场景、4个恢复身份场景。版本为 <code>60192ed54db73ac658ac1a07462916126c32d3a0</code>。<a href="https://github.com/OpenHands/software-agent-sdk/blob/60192ed54db73ac658ac1a07462916126c32d3a0/openhands-sdk/openhands/sdk/conversation/state.py" target="_blank" rel="noreferrer">固定版本会话状态源码</a></p><p>这是一项内部方法探针。保存用的是记录调用的替身，事件与模型也是最小替身，并未安装运行完整软件开发包。记录到“保存调用”，不代表真实文件已耐受断电。</p><table tabindex="0"><thead><tr><th>保存场景</th><th>本次内部实验观察</th><th>可支持的解释</th></tr></thead><tbody><tr><td>普通赋值依次为1、2</td><td>保存收到1、2</td><td>普通更新触发两次保存调用</td></tr><tr><td>在同一批处理块赋值1、2</td><td>保存只收到2</td><td>保存被延后并合并</td></tr><tr><td>块内改成9后抛出受控异常</td><td>异常传播，保存收到9</td><td>这些方法未表现出异常回滚</td></tr><tr><td>嵌套批处理</td><td>保存只收到2</td><td>最外层退出时合并保存</td></tr><tr><td>块内没有变化</td><td>没有保存调用</td><td>未变更状态不会凭空触发保存</td></tr></tbody></table><p>源码中的 <code>__setattr__</code>（属性赋值方法）在批处理深度大于零时标记脏状态；<code>__exit__</code>（上下文退出方法）在深度归零时调用保存，并不依据异常类型撤销赋值。实验把这种方法行为与“出了异常就撤销全部修改”的事务想象区分开来，但没有测试真实存储的写入原子性。</p><h2 id="身份一致不等于效果已知" tabindex="-1">身份一致不等于效果已知 <a class="header-anchor" href="#身份一致不等于效果已知" aria-label="Permalink to &quot;身份一致不等于效果已知&quot;">​</a></h2><p>四个身份场景提供了另一种边界。请求的会话标识与已保存标识不符时，方法在重建事件视图前拒绝恢复。没有提供新智能体时，保留已保存的智能体；提供新智能体时，调用核验替身后替换；替身拒绝时错误传播。这里实际测试的是分支和调用顺序，没有测试原始智能体核验逻辑，也没有测试审批过期、权限撤销或凭据轮换。</p><p>动作匹配的八个场景则说明，待处理动作列表能回答的是“有没有对应的可见事件”。只有动作时，它仍未匹配；正确关联的观察、用户拒绝或按工具调用标识关联的错误会消除未匹配项；关联错误的观察不会消除它，没有可执行内容的事件也不会进入该列表。</p><p>最关键的两个对照是刻意构造的隐藏历史：一条历史里动作尚未执行，另一条里外部效果已经发生但观察没有留下。两者可见日志相同，均只有动作事件，因此得到相同的未匹配结果。这不是两次真实外部执行，也不是观察到的事故；它展示的是输入信息无法区分两种历史。</p><p>研究解释是：待处理列表可以指出需要核对的工作，却不能把观察缺失变成“效果不存在”的事实。是否重试应由应用的幂等或对账协议决定，本实验没有得出自动重放建议。身份兼容、当前授权与外部效果是不同的证据问题。</p><h2 id="另一种恢复单元提供了什么对照" tabindex="-1">另一种恢复单元提供了什么对照 <a class="header-anchor" href="#另一种恢复单元提供了什么对照" aria-label="Permalink to &quot;另一种恢复单元提供了什么对照&quot;">​</a></h2><p>Microsoft Agent Framework（微软智能体框架）的官方文档以工作流与执行器身份描述恢复，要求重建后的拓扑和稳定身份匹配。<a href="https://learn.microsoft.com/en-us/agent-framework/workflows/checkpoints?output=1" target="_blank" rel="noreferrer">检查点文档</a>还把检查点存储视为可信私有基础设施，不能把有限类型解码等同于任意不可信数据安全。</p><p>官方的 <a href="https://learn.microsoft.com/en-us/agent-framework/support/upgrade/python-1-13-0-workflow-checkpoint-upgrade-guide" target="_blank" rel="noreferrer">Python（蟒蛇编程语言）1.13.0检查点升级指南</a>说明，请求待答与响应入口检查点可能具有相同迭代计数，选择恢复点应依据谱系或存储接口，而不能只取最大计数。<a href="https://learn.microsoft.com/en-us/agent-framework/concepts/workflows/builder-and-execution" target="_blank" rel="noreferrer">执行模型文档</a>则描述按同步执行步组织的消息路由与推进边界。</p><p>这些是来源陈述，本轮没有运行验证微软框架。它们与会话状态方法提供的是不同恢复单元的对照，不能成为速度或可靠性排名。两边都需要分别说明本地保存了什么，以及什么额外信息才能确认外部效果。文档快照也没有被假定与另一框架的固定源码处于同一发布版本。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文的实验观察属于本研究方内部依据，不是独立第三方复现。固定源码提供方法实现的一手材料；<a href="https://docs.openhands.dev/sdk/guides/convo-persistence.md" target="_blank" rel="noreferrer">会话持久化指南</a>与微软文档提供各自的公开契约陈述。解释与建议没有被写成这些文档已经承诺的能力。</p><p>本次隔离实验日期为2026-10-23。完整结果记录了保存替身、模型替身、最小事件类、核验替身和替代锁；未测试锁的公平性。实现能运行不代表普遍有效，文档发表和可引用也不代表已经验证其恢复保证。</p><h2 id="仍然没有测到的保证" tabindex="-1">仍然没有测到的保证 <a class="header-anchor" href="#仍然没有测到的保证" aria-label="Permalink to &quot;仍然没有测到的保证&quot;">​</a></h2><p>完整调用方可能在事件日志、工具或存储层另有协调。这项实验没有测试进程崩溃、文件落盘耐久性、秘密值加解密、真实分支重建、当前授权恢复或真实外部动作，因此不能声称整个框架缺少这些保障。</p><p>下一步需要的是完整调用链怎样核对“效果可能发生、观察却未持久化”的动作，以及状态和事件之间的实际存储保证。现在的有界结论是：这些方法提供保存批处理和身份检查；它们自身没有提供异常回滚，也没有足够输入把相同日志背后的外部历史区分开来。</p>',22))])}const k=n(c,[["render",l]]);export{f as __pageData,k as default};
